/* AIVIC_FUNCTION_BUNDLE_START owner=classifyUserSegment exports=classifyUserSegment */
const __aivicBundle_17_classifyUserSegment = (() => {
  function classifyUserSegment(input: {
    age_group: string;
    family_structure: string;
    food_restriction_type: string;
    user_id: string;
  }): { segmentId: string; segmentName: string; characteristics: { [key: string]: any } } {
    if (input["user_id"] === undefined || input["user_id"] === null) { throw new Error("user_id is required"); }
    const { age_group, family_structure, food_restriction_type } = input;
  
    // セグメント定義マトリックス
    const segmentDefinitions = [
      {
        id: "segment_30s_family_allergy",
        name: "30代・子ども有・アレルギー対応",
        conditions: {
          age_group: "30s",
          family_structure: "family_with_children",
          food_restriction_type: "allergy_present",
        },
        characteristics: {
          ageRange: "30-39",
          familySize: "3-4",
          hasAllergy: true,
        },
      },
      {
        id: "segment_20s_single_no_restriction",
        name: "20代・単身・制限なし",
        conditions: {
          age_group: "20s",
          family_structure: "single",
          food_restriction_type: "no_restriction",
        },
        characteristics: {
          ageRange: "20-29",
          familySize: "1",
          hasAllergy: false,
        },
      },
      {
        id: "segment_40s_couple_dietary",
        name: "40代・夫婦・食事制限対応",
        conditions: {
          age_group: "40s",
          family_structure: "couple",
          food_restriction_type: "dietary_restriction",
        },
        characteristics: {
          ageRange: "40-49",
          familySize: "2",
          hasDietaryRestriction: true,
        },
      },
    ];
  
    // 入力条件に合致するセグメントを検索
    const matchedSegment = segmentDefinitions.find(
      (segment) =>
        segment.conditions.age_group === age_group &&
        segment.conditions.family_structure === family_structure &&
        segment.conditions.food_restriction_type === food_restriction_type
    );
  
    // 合致するセグメントが見つからない場合はエラーを throw
    if (!matchedSegment) {
      throw new Error(
        `セグメント条件に合致するセグメントが見つかりません: age_group=${age_group}, family_structure=${family_structure}, food_restriction_type=${food_restriction_type}`
      );
    }
  
    return {
      segmentId: matchedSegment.id,
      segmentName: matchedSegment.name,
      characteristics: matchedSegment.characteristics,
    };
  }
  return { classifyUserSegment };
})();
export const classifyUserSegment = __aivicBundle_17_classifyUserSegment.classifyUserSegment;
/* AIVIC_FUNCTION_BUNDLE_END owner=classifyUserSegment */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDifferentiationEffectIndicators exports=calculateDifferentiationEffectIndicators */
const __aivicBundle_18_calculateDifferentiationEffectIndicators = (() => {
  async function calculateDifferentiationEffectIndicators(
    segmentConditions: { ageGroup: string; region: string; foodRestrictionPresent: boolean }
  ): Promise<DifferentiationResult> {
    const matchingUserCount = await queryMatchingUserCountInternal(segmentConditions);
  
    if (matchingUserCount === 0) {
      return {
        differentiationEffectIndicators: null,
        matchingUserCount: 0,
        mealGenerationSuccessRate: null,
        cookingTimeReductionDegree: null,
        userSatisfactionScore: null,
        status: 'empty_segment',
        segmentConditions,
      };
    }
  
    const mealGenerationSuccessRate = await calculateMealGenerationSuccessRateInternal(segmentConditions);
    const cookingTimeReductionDegree = await calculateCookingTimeReductionDegreeInternal(segmentConditions);
    const userSatisfactionScore = await calculateUserSatisfactionScoreInternal(segmentConditions);
  
    const differentiationEffectIndicators = computeDifferentiationEffectIndicatorsInternal(
      mealGenerationSuccessRate,
      cookingTimeReductionDegree,
      userSatisfactionScore
    );
  
    return {
      differentiationEffectIndicators,
      matchingUserCount,
      mealGenerationSuccessRate,
      cookingTimeReductionDegree,
      userSatisfactionScore,
      status: 'active',
      segmentConditions,
    };
  }
  
  async function queryMatchingUserCountInternal(conditions: { ageGroup: string; region: string; foodRestrictionPresent: boolean }): Promise<number> {
    try {
      const response = await fetch('/api/segments/user-count', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(conditions),
      });
      if (!response.ok) return 0;
      const data = await response.json();
      return data.count ?? 0;
    } catch {
      return 0;
    }
  }
  
  async function calculateMealGenerationSuccessRateInternal(conditions: { ageGroup: string; region: string; foodRestrictionPresent: boolean }): Promise<number> {
    try {
      const response = await fetch('/api/differentiation-effect/meal-success-rate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(conditions),
      });
      if (!response.ok) return 0;
      const data = await response.json();
      return data.successRate ?? 0;
    } catch {
      return 0;
    }
  }
  
  async function calculateCookingTimeReductionDegreeInternal(conditions: { ageGroup: string; region: string; foodRestrictionPresent: boolean }): Promise<number> {
    try {
      const response = await fetch('/api/differentiation-effect/cooking-time-reduction', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(conditions),
      });
      if (!response.ok) return 0;
      const data = await response.json();
      return data.reductionDegree ?? 0;
    } catch {
      return 0;
    }
  }
  
  async function calculateUserSatisfactionScoreInternal(conditions: { ageGroup: string; region: string; foodRestrictionPresent: boolean }): Promise<number> {
    try {
      const response = await fetch('/api/differentiation-effect/satisfaction-score', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(conditions),
      });
      if (!response.ok) return 0;
      const data = await response.json();
      return data.satisfactionScore ?? 0;
    } catch {
      return 0;
    }
  }
  
  function computeDifferentiationEffectIndicatorsInternal(
    successRate: number,
    cookingTimeReduction: number,
    satisfactionScore: number
  ): number {
    const weights = {
      successRate: 0.4,
      cookingTimeReduction: 0.3,
      satisfactionScore: 0.3,
    };
  
    const normalizedSuccessRate = Math.min(100, Math.max(0, successRate));
    const normalizedCookingTime = Math.min(100, Math.max(0, cookingTimeReduction));
    const normalizedSatisfaction = Math.min(5, Math.max(0, satisfactionScore)) * 20;
  
    const indicator =
      normalizedSuccessRate * weights.successRate +
      normalizedCookingTime * weights.cookingTimeReduction +
      normalizedSatisfaction * weights.satisfactionScore;
  
    return Math.round(indicator * 10) / 10;
  }
  return { calculateDifferentiationEffectIndicators };
})();
export const calculateDifferentiationEffectIndicators = __aivicBundle_18_calculateDifferentiationEffectIndicators.calculateDifferentiationEffectIndicators;
