/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementMetrics exports=calculateAlgorithmImprovementMetrics */
const __aivicBundle_19_calculateAlgorithmImprovementMetrics = (() => {
  function calculateAlgorithmImprovementMetrics(input: {
    pre_improvement_menus: Array<{
      menu_id: string;
      algorithm_version: string;
      nutrition_balance_score: number;
      ingredient_compatibility_score: number;
      cooking_time_minutes: number;
      cooking_time_limit_minutes: number;
      is_successful: boolean;
      generated_at: Date;
    }>;
    post_improvement_menus: Array<{
      menu_id: string;
      algorithm_version: string;
      nutrition_balance_score: number;
      ingredient_compatibility_score: number;
      cooking_time_minutes: number;
      cooking_time_limit_minutes: number;
      is_successful: boolean;
      generated_at: Date;
    }>;
    nutrition_balance_threshold: number;
    ingredient_compatibility_threshold: number;
    cooking_time_threshold_minutes: number;
  }): AlgorithmMetrics {
    if (input["nutrition_balance_threshold"] === undefined || input["nutrition_balance_threshold"] === null) { throw new Error("nutrition_balance_threshold is required"); }
    if (input["ingredient_compatibility_threshold"] === undefined || input["ingredient_compatibility_threshold"] === null) { throw new Error("ingredient_compatibility_threshold is required"); }
    if (input["cooking_time_threshold_minutes"] === undefined || input["cooking_time_threshold_minutes"] === null) { throw new Error("cooking_time_threshold_minutes is required"); }
    const pre_improvement_success_count = input.pre_improvement_menus.filter(
      (menu) => menu.is_successful
    ).length;
  
    const pre_improvement_success_rate =
      input.pre_improvement_menus.length > 0
        ? (pre_improvement_success_count / input.pre_improvement_menus.length) * 100
        : 0;
  
    const post_improvement_success_count = input.post_improvement_menus.filter(
      (menu) => menu.is_successful
    ).length;
  
    const post_improvement_success_rate =
      input.post_improvement_menus.length > 0
        ? (post_improvement_success_count / input.post_improvement_menus.length) * 100
        : 0;
  
    const improvement_rate_difference =
      post_improvement_success_rate - pre_improvement_success_rate;
  
    const improvement_success_count_difference =
      post_improvement_success_count - pre_improvement_success_count;
  
    const improvement_multiplier =
      pre_improvement_success_count > 0
        ? post_improvement_success_count / pre_improvement_success_count
        : post_improvement_success_count > 0
          ? Infinity
          : 1;
  
    const aggregated_at = new Date().toISOString();
  
    return {
      pre_improvement_success_count,
      pre_improvement_success_rate,
      post_improvement_success_count,
      post_improvement_success_rate,
      improvement_rate_difference,
      improvement_success_count_difference,
      improvement_multiplier,
      aggregated_at,
    };
  }
  return { calculateAlgorithmImprovementMetrics };
})();
export const calculateAlgorithmImprovementMetrics = __aivicBundle_19_calculateAlgorithmImprovementMetrics.calculateAlgorithmImprovementMetrics;
