/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmImprovementQuantitatively exports=compareAlgorithmImprovementQuantitatively */
const __aivicBundle_20_compareAlgorithmImprovementQuantitatively = (() => {
  function compareAlgorithmImprovementQuantitatively(input: {
    beforeAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    afterAlgorithmDataSet: Array<{
      mealGenerationId: string;
      timestamp: Date;
      satisfactionScore: number;
      completionRate: number;
      rejectionRate: number;
      cookingTimeMinutes: number;
      algorithmVersion: string;
    }>;
    beforePeriodStartDate: Date;
    beforePeriodEndDate: Date;
    afterPeriodStartDate: Date;
    afterPeriodEndDate: Date;
    minimumDataRequirementDays: number;
  }): ComparisonResult {
    const beforeStartTime = input.beforePeriodStartDate.getTime();
    const beforeEndTime = input.beforePeriodEndDate.getTime();
    const afterStartTime = input.afterPeriodStartDate.getTime();
    const afterEndTime = input.afterPeriodEndDate.getTime();
  
    const beforeDurationMs = beforeEndTime - beforeStartTime;
    const afterDurationMs = afterEndTime - afterStartTime;
  
    const beforeDurationDays = beforeDurationMs / (1000 * 60 * 60 * 24);
    const afterDurationDays = afterDurationMs / (1000 * 60 * 60 * 24);
  
    const minimumDurationMs = input.minimumDataRequirementDays * 24 * 60 * 60 * 1000;
  
    if (beforeDurationMs < minimumDurationMs || afterDurationMs < minimumDurationMs) {
      return {
        isAggregatable: false,
        errorMessage: `データ期間が不足しています。${input.minimumDataRequirementDays}日以上のデータが必要です。`,
        dataCollectionDaysBefore: Math.ceil(beforeDurationDays),
        dataCollectionDaysAfter: Math.ceil(afterDurationDays)
      };
    }
  
    const beforeAvgSatisfaction =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, item) => sum + item.satisfactionScore, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgSatisfaction =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, item) => sum + item.satisfactionScore, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const beforeAvgCompletionRate =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, item) => sum + item.completionRate, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgCompletionRate =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, item) => sum + item.completionRate, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const beforeAvgRejectionRate =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, item) => sum + item.rejectionRate, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgRejectionRate =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, item) => sum + item.rejectionRate, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const beforeAvgCookingTime =
      input.beforeAlgorithmDataSet.length > 0
        ? input.beforeAlgorithmDataSet.reduce((sum, item) => sum + item.cookingTimeMinutes, 0) /
          input.beforeAlgorithmDataSet.length
        : 0;
  
    const afterAvgCookingTime =
      input.afterAlgorithmDataSet.length > 0
        ? input.afterAlgorithmDataSet.reduce((sum, item) => sum + item.cookingTimeMinutes, 0) /
          input.afterAlgorithmDataSet.length
        : 0;
  
    const satisfactionImprovement = ((afterAvgSatisfaction - beforeAvgSatisfaction) / beforeAvgSatisfaction) * 100;
    const completionRateImprovement = ((afterAvgCompletionRate - beforeAvgCompletionRate) / beforeAvgCompletionRate) * 100;
    const rejectionRateReduction = ((beforeAvgRejectionRate - afterAvgRejectionRate) / beforeAvgRejectionRate) * 100;
    const cookingTimeReduction = ((beforeAvgCookingTime - afterAvgCookingTime) / beforeAvgCookingTime) * 100;
  
    return {
      isAggregatable: true,
      aggregatedComparison: {
        satisfactionImprovement: Math.round(satisfactionImprovement * 10) / 10,
        completionRateImprovement: Math.round(completionRateImprovement * 10) / 10,
        rejectionRateReduction: Math.round(rejectionRateReduction * 10) / 10,
        cookingTimeReduction: Math.round(cookingTimeReduction * 10) / 10
      },
      dataCollectionDaysBefore: Math.ceil(beforeDurationDays),
      dataCollectionDaysAfter: Math.ceil(afterDurationDays)
    };
  }
  return { compareAlgorithmImprovementQuantitatively };
})();
export const compareAlgorithmImprovementQuantitatively = __aivicBundle_20_compareAlgorithmImprovementQuantitatively.compareAlgorithmImprovementQuantitatively;
