/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealAfterAlgorithmImprovement exports=validateMealAfterAlgorithmImprovement */
const __aivicBundle_24_validateMealAfterAlgorithmImprovement = (() => {
  function validateMealAfterAlgorithmImprovement(
    mealData: {
      mealId: string;
      date: string;
      dishes: Array<{
        dishId: string;
        name: string;
        caloriesPer100g: number;
        servingSize: number;
        allergens: string[];
      }>;
    },
    constraints: {
      dailyCalorieLimit: number;
      allowedAllergens: string[];
      forbiddenAllergens: string[];
      proteinMinGrams: number;
      sodiumMaxMg: number;
    },
    familyMember: {
      memberId: string;
      age: number;
      gender: string;
    }
  ): MealAfterImprovementValidation {
    if (familyMember["age"] === undefined || familyMember["age"] === null) { throw new Error("age is required"); }
    if (familyMember["gender"] === undefined || familyMember["gender"] === null) { throw new Error("gender is required"); }
    if (mealData["date"] === undefined || mealData["date"] === null) { throw new Error("date is required"); }
    if (constraints["allowedAllergens"] === undefined || constraints["allowedAllergens"] === null) { throw new Error("allowedAllergens is required"); }
    if (mealData.date === undefined || mealData.date === null || String(mealData.date).trim() === "") {
      throw new Error("date is required");
    }
    if (constraints.allowedAllergens === undefined || constraints.allowedAllergens === null) {
      throw new Error("allowedAllergens is required");
    }
    if (familyMember.memberId === undefined || familyMember.memberId === null || String(familyMember.memberId).trim() === "") {
      throw new Error("memberId is required");
    }
  
    const violationReasons: string[] = [];
  
    let totalCalories = 0;
    let totalSodium = 0;
    let totalProtein = 0;
    const allAllergens: Set<string> = new Set();
  
    for (const dish of mealData.dishes) {
      const dishCalories = dish.caloriesPer100g * (dish.servingSize / 100);
      totalCalories += dishCalories;
  
      const dishSodium = dish.caloriesPer100g > 200 ? (dish.servingSize / 100) * 400 : (dish.servingSize / 100) * 200;
      totalSodium += dishSodium;
  
      const proteinContent = dish.caloriesPer100g > 150 ? (dish.servingSize / 100) * 20 : (dish.servingSize / 100) * 5;
      totalProtein += proteinContent;
  
      for (const allergen of dish.allergens) {
        allAllergens.add(allergen);
      }
    }
  
    if (totalCalories > constraints.dailyCalorieLimit) {
      violationReasons.push(`カロリー上限超過: ${Math.round(totalCalories)}kcal (上限: ${constraints.dailyCalorieLimit}kcal)`);
    }
  
    for (const allergen of allAllergens) {
      if (constraints.forbiddenAllergens.includes(allergen)) {
        violationReasons.push(`指定アレルゲン含有: ${allergen}`);
      }
    }
  
    if (totalSodium > constraints.sodiumMaxMg) {
      violationReasons.push(`塩分上限超過: ${Math.round(totalSodium)}mg (上限: ${constraints.sodiumMaxMg}mg)`);
    }
  
    if (totalProtein < constraints.proteinMinGrams) {
      violationReasons.push(`タンパク質不足: ${Math.round(totalProtein)}g (最小: ${constraints.proteinMinGrams}g)`);
    }
  
    const isAppropriate = violationReasons.length === 0;
    const timestamp = new Date().toISOString();
  
    return {
      isAppropriate,
      violationReasons,
      mealId: mealData.mealId,
      timestamp
    };
  }
  return { validateMealAfterAlgorithmImprovement };
})();
