/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealPlans exports=validateMealPlans */
const __aivicBundle_26_validateMealPlans = (() => {
  function validateMealPlans(input: MealPlanValidationInput): {
    statusCode: number;
    isValid: boolean;
    mealValidations: MealValidationResult[];
    message: string;
  } {
    const { familyComposition, mealPlans } = input;
  
    // 家族構成から全ての制限条件とアレルギーを集約
    const allRestrictions = new Set<string>();
    const allAllergies = new Set<string>();
  
    for (const member of familyComposition.members) {
      if (member.restrictions) {
        member.restrictions.forEach((r) => allRestrictions.add(r));
      }
      if (member.allergies) {
        member.allergies.forEach((a) => allAllergies.add(a));
      }
    }
  
    const hasRestrictions =
      allRestrictions.size > 0 || allAllergies.size > 0;
  
    // 各献立を検証
    const mealValidations: MealValidationResult[] = [];
  
    for (const mealPlan of mealPlans) {
      let restrictionCheckPassed = true;
      let allergyCheckPassed = true;
      let nutritionCheckPassed = true;
  
      // 制限条件がない場合は全て有効
      if (!hasRestrictions) {
        restrictionCheckPassed = true;
        allergyCheckPassed = true;
        nutritionCheckPassed = true;
      } else {
        // 制限条件がある場合、各献立の食材をチェック
        const allIngredients = new Set<string>();
        for (const meal of mealPlan.meals) {
          meal.ingredients.forEach((ing) => allIngredients.add(ing));
        }
  
        // アレルギーチェック
        for (const allergen of allAllergies) {
          if (allIngredients.has(allergen)) {
            allergyCheckPassed = false;
            break;
          }
        }
  
        // 制限条件チェック（制限条件が食材に含まれていないか確認）
        for (const restriction of allRestrictions) {
          if (allIngredients.has(restriction)) {
            restrictionCheckPassed = false;
            break;
          }
        }
  
        // 栄養チェック（基本的には常に合格とする）
        nutritionCheckPassed = true;
      }
  
      const isValid =
        restrictionCheckPassed && allergyCheckPassed && nutritionCheckPassed;
  
      mealValidations.push({
        isValid,
        mealPlanId: mealPlan.mealPlanId,
        details: {
          restrictionCheck: restrictionCheckPassed ? "passed" : "failed",
          allergyCheck: allergyCheckPassed ? "passed" : "failed",
          nutritionCheck: nutritionCheckPassed ? "passed" : "failed",
        },
      });
    }
  
    // 全献立が有効かどうかを判定
    const allValid = mealValidations.every((v) => v.isValid);
  
    let message: string;
    if (!hasRestrictions) {
      message = "制限条件がないため全ての献立が有効です";
    } else if (allValid) {
      message = "全ての献立が制限条件を満たしています";
    } else {
      message = "一部の献立が制限条件を満たしていません";
    }
  
    return {
      statusCode: 200,
      isValid: allValid,
      mealValidations,
      message,
    };
  }
  return { validateMealPlans };
})();
export const validateMealPlans = __aivicBundle_26_validateMealPlans.validateMealPlans;
