        return {
          ruleId: stored.ruleId,
          seasonPattern: stored.seasonPattern,
          discountRateThreshold: stored.discountRateThreshold,
          salePeriodStart: stored.salePeriodStart,
          salePeriodEnd: stored.salePeriodEnd,
          lastUpdated: stored.lastUpdated,
          version: stored.version,
          isPersisted: stored.isPersisted,
        };
