/* AIVIC_FUNCTION_BUNDLE_START owner=integrateSeasonalPatternAndDiscountRules exports=integrateSeasonalPatternAndDiscountRules */
const __aivicBundle_35_integrateSeasonalPatternAndDiscountRules = (() => {
  function integrateSeasonalPatternAndDiscountRules(
    ingredientInput: any,
    priorityRuleConfig: any
  ): any {
    const {
      ingredientId,
      ingredientName,
      seasonalPattern,
      discountRate,
      salePeriodStartDate,
      salePeriodEndDate,
    } = ingredientInput;
  
    const {
      priorityOrder,
      seasonalPatternWeight,
      discountRateWeight,
      salePeriodWeight,
    } = priorityRuleConfig;
  
    // Parse dates for range validation
    const startDate = new Date(salePeriodStartDate);
    const endDate = new Date(salePeriodEndDate);
  
    // Validate that start date is less than or equal to end date (range ordering)
    const isValidSalePeriod = startDate <= endDate;
  
    // Check if start and end dates are the same calendar day by comparing ISO date strings
    const startDateString = startDate.toISOString().split("T")[0];
    const endDateString = endDate.toISOString().split("T")[0];
    const sameDatePeriodFlag = startDateString === endDateString;
  
    // Calculate priority score based on weights and priority order
    let priorityScore = 0;
  
    if (priorityOrder && priorityOrder.length > 0) {
      // Normalize weights
      const totalWeight =
        seasonalPatternWeight + discountRateWeight + salePeriodWeight;
      const normalizedSeasonalWeight = seasonalPatternWeight / totalWeight;
      const normalizedDiscountWeight = discountRateWeight / totalWeight;
      const normalizedSalePeriodWeight = salePeriodWeight / totalWeight;
  
      // Calculate component scores
      const seasonalScore = seasonalPattern ? 10 : 0;
      const discountScore = (discountRate / 100) * 10;
      const salePeriodScore = isValidSalePeriod ? 10 : 0;
  
      // Apply weights based on priority order
      priorityScore = Math.round(
        seasonalScore * normalizedSeasonalWeight * 10 +
          discountScore * normalizedDiscountWeight * 10 +
          salePeriodScore * normalizedSalePeriodWeight * 10
      );
  
      // Clamp to 0-100 range
      priorityScore = Math.max(0, Math.min(100, priorityScore));
    }
  
    // Determine if ingredient can be included in menu
    const canBeIncludedInMenu = isValidSalePeriod && priorityScore > 0;
  
    // Determine generation log status
    const generationLogStatus = isValidSalePeriod
      ? "processed_successfully"
      : "validation_failed";
  
    return {
      ingredientId,
      ingredientName,
      seasonalPattern,
      discountRate,
      salePeriodStartDate,
      salePeriodEndDate,
      isValidSalePeriod,
      priorityScore,
      canBeIncludedInMenu,
      generationLogStatus,
      sameDatePeriodFlag,
    };
  }
  return { integrateSeasonalPatternAndDiscountRules };
})();
