/* AIVIC_FUNCTION_BUNDLE_START owner=assignProxyParticipant exports=assignProxyParticipant */
const __aivicBundle_51_assignProxyParticipant = (() => {
  function assignProxyParticipant(input: {
    meeting_id: string;
    participants: Array<{
      participant_id: string;
      name: string;
      status: string;
      role: string;
    }>;
    proxy_candidate_id: string;
  }): {
    assignmentStatus: string;
    originalParticipant: string;
    proxyParticipant: string;
    assignmentTimestamp: string;
    isValid: boolean;
    validationErrors: string[];
  } {
    if (input["meeting_id"] === undefined || input["meeting_id"] === null) { throw new Error("meeting_id is required"); }
    const { participants, proxy_candidate_id } = input;
    const assignmentTimestamp = new Date().toISOString();
    const validationErrors: string[] = [];
  
    // Check if all participants are absent
    const allAbsent = participants.every((p) => p.status === 'absent');
    if (allAbsent) {
      throw new Error('全参加者が欠席しているため、代理参加者の割り当てができません');
    }
  
    // Find an absent participant to assign proxy to
    const absentParticipant = participants.find((p) => p.status === 'absent');
  
    if (!absentParticipant) {
      validationErrors.push('欠席している参加者が見つかりません');
      return {
        assignmentStatus: 'rejected',
        originalParticipant: '',
        proxyParticipant: proxy_candidate_id,
        assignmentTimestamp,
        isValid: false,
        validationErrors,
      };
    }
  
    // Validate proxy candidate is not the same as original participant
    if (proxy_candidate_id === absentParticipant.participant_id) {
      validationErrors.push('代理人は本人と異なる必要があります');
      return {
        assignmentStatus: 'rejected',
        originalParticipant: absentParticipant.participant_id,
        proxyParticipant: proxy_candidate_id,
        assignmentTimestamp,
        isValid: false,
        validationErrors,
      };
    }
  
    // Validate proxy candidate exists in participants or is a valid external candidate
    const proxyExists = participants.some(
      (p) => p.participant_id === proxy_candidate_id
    );
  
    if (!proxyExists && !proxy_candidate_id) {
      validationErrors.push('代理人候補が指定されていません');
      return {
        assignmentStatus: 'rejected',
        originalParticipant: absentParticipant.participant_id,
        proxyParticipant: proxy_candidate_id,
        assignmentTimestamp,
        isValid: false,
        validationErrors,
      };
    }
  
    // Check for conflict of interest (proxy cannot be from conflicting role)
    const conflictingRoles = ['product_manager'];
    const proxyParticipant = participants.find(
      (p) => p.participant_id === proxy_candidate_id
    );
  
    if (
      proxyParticipant &&
      conflictingRoles.includes(proxyParticipant.role) &&
      conflictingRoles.includes(absentParticipant.role)
    ) {
      validationErrors.push('代理人と本人の役割に利益相反があります');
      return {
        assignmentStatus: 'rejected',
        originalParticipant: absentParticipant.participant_id,
        proxyParticipant: proxy_candidate_id,
        assignmentTimestamp,
        isValid: false,
        validationErrors,
      };
    }
  
    // All validations passed
    return {
      assignmentStatus: 'approved',
      originalParticipant: absentParticipant.participant_id,
      proxyParticipant: proxy_candidate_id,
      assignmentTimestamp,
      isValid: true,
      validationErrors: [],
    };
  }
  return { assignProxyParticipant };
})();
export const assignProxyParticipant = __aivicBundle_51_assignProxyParticipant.assignProxyParticipant;
