/* AIVIC_FUNCTION_BUNDLE_START owner=judgeQualityGate exports=judgeQualityGate */
const __aivicBundle_53_judgeQualityGate = (() => {
  function judgeQualityGate(input: any): any {
    const proposal = input;
  
    // 成功率の判定
    const success_rate_judge =
      proposal.success_rate_after >= proposal.success_rate_threshold;
  
    // 調理時間削減の判定
    const cooking_time_reduction_judge =
      proposal.cooking_time_reduction_before -
        proposal.cooking_time_reduction_after >=
      proposal.cooking_time_reduction_threshold;
  
    // ユーザー満足度の判定
    const user_satisfaction_judge =
      proposal.user_satisfaction_after >= proposal.user_satisfaction_threshold;
  
    // テスト環境の判定
    const test_environment_judge = proposal.test_environment_pass === true;
  
    // リグレッションテストの判定
    const regression_test_judge = proposal.regression_test_pass === true;
  
    // コードレビューの判定
    const code_review_judge = proposal.code_review_pass === true;
  
    // 全ての基準が満たされているかを判定
    const all_criteria_met =
      success_rate_judge &&
      cooking_time_reduction_judge &&
      user_satisfaction_judge &&
      test_environment_judge &&
      regression_test_judge &&
      code_review_judge;
  
    // 本番昇格判定：全基準が満たされている場合のみ合格
    const is_passed = all_criteria_met;
    const promotion_eligible = all_criteria_met;
  
    return {
      is_passed,
      promotion_eligible,
      success_rate_judge,
      cooking_time_reduction_judge,
      user_satisfaction_judge,
      test_environment_judge,
      regression_test_judge,
      code_review_judge,
      all_criteria_met,
    };
  }
  return { judgeQualityGate };
})();
