/* AIVIC_FUNCTION_BUNDLE_START owner=validateQualityGate exports=validateQualityGate */
const __aivicBundle_54_validateQualityGate = (() => {
  interface ValidateQualityGateSimpleResult {
    [key: string]: any;
  }
  
  interface ValidateQualityGateComplexResult {
    deploymentApproved: boolean;
    status: string;
    failureDetails: Array<{
      metricName: string;
      requiredValue: number;
      actualValue: number;
    }>;
  }
  
  type ValidateQualityGateResult = ValidateQualityGateSimpleResult | ValidateQualityGateComplexResult;
  
  interface ValidateQualityGateInput {
    improvement_id?: string;
    metric_value?: number;
    pass_threshold?: number;
    proposalId?: string;
    algorithmVersion?: string;
    testCoverage?: number;
    performanceScore?: number;
    successRate?: number;
    deploymentDate?: string;
  }
  
   function validateQualityGate(input: ValidateQualityGateInput): ValidateQualityGateResult {
    const hasSimpleMetrics = 'improvement_id' in input && 'metric_value' in input && 'pass_threshold' in input;
    const hasComplexMetrics = 'proposalId' in input;
  
    if (hasSimpleMetrics) {
      const improvementId = input.improvement_id;
      const metricValue = input.metric_value;
      const passThreshold = input.pass_threshold;
  
      if (!improvementId || improvementId === '') {
        throw new Error('改善IDが空です');
      }
      if (metricValue === undefined || metricValue === null || metricValue < 0) {
        throw new Error('メトリクス値が無効です');
      }
      if (passThreshold === undefined || passThreshold === null || passThreshold < 0) {
        throw new Error('閾値が無効です');
      }
  
      const passed = metricValue >= passThreshold;
      const reason = passed ? '合格' : '不合格';
  
      return {
        improvement_id: improvementId,
        passed,
        metric_value: metricValue,
        threshold: passThreshold,
        reason,
      };
    }
  
    if (hasComplexMetrics) {
      const requiredTestCoverage = 80;
      const requiredPerformanceScore = 75;
      const requiredSuccessRate = 85;
  
      const failureDetails: Array<{
        metricName: string;
        requiredValue: number;
        actualValue: number;
      }> = [];
  
      if (input.testCoverage !== undefined && input.testCoverage < requiredTestCoverage) {
        failureDetails.push({
          metricName: 'testCoverage',
          requiredValue: requiredTestCoverage,
          actualValue: input.testCoverage,
        });
      }
  
      if (input.performanceScore !== undefined && input.performanceScore < requiredPerformanceScore) {
        failureDetails.push({
          metricName: 'performanceScore',
          requiredValue: requiredPerformanceScore,
          actualValue: input.performanceScore,
        });
      }
  
      if (input.successRate !== undefined && input.successRate < requiredSuccessRate) {
        failureDetails.push({
          metricName: 'successRate',
          requiredValue: requiredSuccessRate,
          actualValue: input.successRate,
        });
      }
  
      const deploymentApproved = failureDetails.length === 0;
      const status = deploymentApproved ? 'PASSED' : 'FAILED';
  
      return {
        deploymentApproved,
        status,
        failureDetails,
      };
    }
  
    throw new Error('Invalid input: missing required fields');
  }
  return { validateQualityGate };
})();
