/* AIVIC_FUNCTION_BUNDLE_START owner=confirmMeetingAttendance exports=confirmMeetingAttendance */
const __aivicBundle_55_confirmMeetingAttendance = (() => {
  function confirmMeetingAttendance(
    meetingData: any,
    confirmationData: any
  ): any {
    if (!meetingData || !confirmationData) {
      return {
        confirmationStatus: 'failed',
        participantId: confirmationData?.attendeeId || '',
        meetingId: confirmationData?.meetingId || '',
        attendanceRecorded: false,
        recordedAt: '',
        validationErrors: ['Invalid input data'],
      };
    }
  
    const { meetingId, attendees = [] } = meetingData;
    const { attendeeId, confirmationAction, confirmedAt } = confirmationData;
  
    const validationErrors: string[] = [];
  
    if (!meetingId || !attendeeId || !confirmationAction) {
      validationErrors.push('Missing required fields');
    }
  
    if (confirmationAction !== 'confirm_attendance') {
      validationErrors.push('Invalid confirmation action');
    }
  
    if (validationErrors.length > 0) {
      return {
        confirmationStatus: 'failed',
        participantId: attendeeId,
        meetingId,
        attendanceRecorded: false,
        recordedAt: '',
        validationErrors,
      };
    }
  
    const updatedAttendees = attendees.map((attendee: any) => {
      if (attendee.attendeeId === attendeeId) {
        return {
          ...attendee,
          status: 'confirmed',
          confirmedAt: confirmedAt instanceof Date ? confirmedAt : new Date(confirmedAt),
        };
      }
      return attendee;
    });
  
    const allConfirmed = updatedAttendees.every(
      (attendee: any) => attendee.status === 'confirmed'
    );
  
    const newMeetingStatus = allConfirmed ? 'confirmed' : 'pending_confirmation';
    const meetingConfirmedAt = allConfirmed ? confirmedAt : undefined;
  
    const result: any = {
      meetingId,
      meetingTitle: meetingData.meetingTitle,
      scheduledStartTime: meetingData.scheduledStartTime,
      scheduledEndTime: meetingData.scheduledEndTime,
      createdAt: meetingData.createdAt,
      createdBy: meetingData.createdBy,
      meetingStatus: newMeetingStatus,
      attendees: updatedAttendees,
      isConfirmed: allConfirmed,
    };
  
    if (meetingConfirmedAt) {
      result.meetingConfirmedAt = meetingConfirmedAt instanceof Date ? meetingConfirmedAt : new Date(meetingConfirmedAt);
    }
  
    return result;
  }
  return { confirmMeetingAttendance };
})();
